var now = new Date();
var out = [];
var i;
for (i = 0; i < 2; i++) {
  var d = new Date(now.getTime() - i * 86400000);
  out.push({ json: { d: d.toISOString().slice(0, 10) } });
}
return out;

var SIG = {
  "2.02": ["earnings", 92, "Results of Operations and Financial Condition"],
  "4.02": ["restatement", 90, "Non-Reliance on Previously Issued Financial Statements"],
  "3.01": ["delisting_notice", 86, "Notice of Delisting or Failure to Satisfy a Listing Rule"],
  "2.01": ["acquisition_completed", 82, "Completion of Acquisition or Disposition of Assets"],
  "5.01": ["control_change", 82, "Changes in Control of Registrant"],
  "2.04": ["debt_acceleration", 78, "Triggering Events That Accelerate a Direct Financial Obligation"],
  "2.06": ["impairment", 74, "Material Impairments"],
  "4.01": ["auditor_change", 72, "Changes in Registrant Certifying Accountant"],
  "1.01": ["material_agreement", 66, "Entry into a Material Definitive Agreement"],
  "2.05": ["restructuring", 66, "Costs Associated with Exit or Disposal Activities"],
  "1.02": ["agreement_terminated", 62, "Termination of a Material Definitive Agreement"],
  "5.02": ["officer_change", 60, "Departure or Election of Directors or Officers"],
  "3.02": ["equity_dilution", 56, "Unregistered Sale of Equity Securities"],
  "2.03": ["new_debt", 52, "Creation of a Direct Financial Obligation"]
};

function splitName(dn) {
  var ci = dn.lastIndexOf("(CIK");
  if (ci < 0) { return { company: dn.trim(), ticker: null }; }
  var head = dn.substring(0, ci);
  var close = head.lastIndexOf(")");
  if (close < 0) { return { company: head.trim(), ticker: null }; }
  var open = head.lastIndexOf("(", close);
  if (open < 0) { return { company: head.trim(), ticker: null }; }
  var raw = head.substring(open + 1, close).trim();
  var first = raw.split(",")[0].trim().toUpperCase();
  if (!first || first.length > 12) { return { company: head.trim(), ticker: null }; }
  return { company: head.substring(0, open).trim(), ticker: first };
}

var pages = $input.all();
var rows = [];
var seen = {};
var scanned = 0;
var serverTotal = 0;
var days = {};
var i, j, k;

for (i = 0; i < pages.length; i++) {
  var body = pages[i].json || {};
  var hh = (body.hits && body.hits.hits) ? body.hits.hits : [];
  if (body.hits && body.hits.total && body.hits.total.value > serverTotal) {
    serverTotal = body.hits.total.value;
  }
  for (j = 0; j < hh.length; j++) {
    var s = hh[j]._source || {};
    scanned = scanned + 1;
    if (s.file_date) { days[s.file_date] = (days[s.file_date] || 0) + 1; }
    var its = s.items || [];
    var adsh = s.adsh || null;
    var cikStr = (s.ciks && s.ciks[0]) ? s.ciks[0] : null;
    var cikInt = cikStr ? parseInt(cikStr, 10) : null;
    if (!adsh || !cikInt) { continue; }
    var dn = (s.display_names && s.display_names[0]) ? s.display_names[0] : "";
    var nm = splitName(dn);
    var nodash = adsh.split("-").join("");
    var url = "https://www.sec.gov/Archives/edgar/data/" + cikInt + "/" + nodash + "/" + adsh + "-index.htm";
    for (k = 0; k < its.length; k++) {
      var code = its[k];
      var def = SIG[code];
      if (!def) { continue; }
      var key = adsh + "|" + code;
      if (seen[key]) { continue; }
      seen[key] = true;
      rows.push({
        kind: code === "2.02" ? "earnings" : "filing",
        ticker: nm.ticker,
        cik: cikInt,
        company: nm.company,
        event_type: def[0],
        item_code: code,
        items: its,
        accession: adsh,
        filed_at: s.file_date || null,
        score: def[1],
        source: "SEC EDGAR full-text search (8-K)",
        headline: nm.company + (nm.ticker ? " (" + nm.ticker + ")" : "") + " - " + def[2],
        detail: "8-K item " + code + " (" + def[2] + ") filed " + (s.file_date || "unknown") +
                ". All items on this filing: " + its.join(", ") +
                ". Accession " + adsh + ". CIK " + cikInt + "." +
                (s.period_ending ? " Period ending " + s.period_ending + "." : ""),
        url: url
      });
    }
  }
}

var earnings = 0;
for (i = 0; i < rows.length; i++) { if (rows[i].item_code === "2.02") { earnings = earnings + 1; } }

return [{ json: {
  rows: rows,
  n: rows.length,
  earnings: earnings,
  pages_fetched: pages.length,
  hits_scanned: scanned,
  server_total_max_day: serverTotal,
  per_day: days
} }];

var src = $('Filter Item Codes').first().json.rows || [];
var seen = {};
var out = [];
var i;
for (i = 0; i < src.length; i++) {
  var r = src[i];
  if (r.item_code !== "2.02") { continue; }
  if (!r.cik) { continue; }
  if (seen[r.cik]) { continue; }
  seen[r.cik] = true;
  var padded = ("0000000000" + r.cik).slice(-10);
  out.push({ json: { cik: r.cik, cik_padded: padded, ticker: r.ticker } });
}
return out;

var earn = $('Filter Item Codes').first().json.rows || [];
var subs = $input.all();
var timeByAccn = {};
var i, j;

for (i = 0; i < subs.length; i++) {
  var b = subs[i].json || {};
  var rec = (b.filings && b.filings.recent) ? b.filings.recent : null;
  if (!rec || !rec.accessionNumber) { continue; }
  for (j = 0; j < rec.accessionNumber.length; j++) {
    if (rec.acceptanceDateTime && rec.acceptanceDateTime[j]) {
      timeByAccn[rec.accessionNumber[j]] = rec.acceptanceDateTime[j];
    }
  }
}

var rows = [];
for (i = 0; i < earn.length; i++) {
  var r = earn[i];
  if (r.item_code !== "2.02") { continue; }
  var t = timeByAccn[r.accession];
  if (!t) { continue; }
  rows.push({
    kind: r.kind, ticker: r.ticker, cik: r.cik, company: r.company,
    event_type: r.event_type, item_code: r.item_code, items: r.items,
    accession: r.accession, filed_at: r.filed_at, accepted_at: t,
    score: r.score, source: r.source, headline: r.headline,
    detail: r.detail + " Accepted by EDGAR at " + t + ".",
    url: r.url
  });
}

return [{ json: { rows: rows, n: rows.length, companies_queried: subs.length } }];
